<?php
/** @var array<string, mixed> $attributes */
declare( strict_types=1 );
if ( ! defined( 'ABSPATH' ) ) { exit; }
$items = nextsaas_items( $attributes, 'items' ); $total = count( $items ); $uid = wp_unique_id( 'testimonial-' ); ?>
<section <?php echo nextsaas_section_attrs( 'home-testimonial', $attributes, array( 'section', 'testimonial' ) ); ?>><div class="container grid-1-2"><div><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><?php echo nextsaas_icon( 'quote' ); ?><p class="testimonial-note" data-nextsaas-rich="note"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'note' ) ); ?></p></div><div class="testimonial-slider" role="region" aria-roledescription="carousel" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'carouselLabel' ) ); ?>" tabindex="0" data-nextsaas-testimonial><div id="<?php echo esc_attr( $uid ); ?>-slides" aria-live="polite" aria-atomic="true"><?php foreach ( $items as $index => $item ) : ?><figure class="testimonial-slide" role="group" aria-roledescription="slide" aria-label="<?php echo esc_attr( sprintf( '%1$d of %2$d', $index + 1, $total ) ); ?>"<?php echo 0 === $index ? '' : ' hidden'; ?>><blockquote><?php echo esc_html( (string) ( $item['heading'] ?? '' ) ); ?></blockquote><figcaption><?php echo esc_html( (string) ( $item['meta'] ?? '' ) ); ?><br><?php echo esc_html( (string) ( $item['body'] ?? '' ) ); ?></figcaption></figure><?php endforeach; ?></div><div class="testimonial-controls"><span class="testimonial-status" role="status" data-nextsaas-testimonial-count>01 / <?php echo esc_html( str_pad( (string) $total, 2, '0', STR_PAD_LEFT ) ); ?></span><button type="button" class="carousel-btn" aria-label="<?php esc_attr_e( 'Previous testimonial', 'nextsaas' ); ?>" aria-controls="<?php echo esc_attr( $uid ); ?>-slides" data-nextsaas-testimonial-prev><?php echo nextsaas_icon( 'arrow-left' ); ?></button><button type="button" class="carousel-btn" aria-label="<?php esc_attr_e( 'Next testimonial', 'nextsaas' ); ?>" aria-controls="<?php echo esc_attr( $uid ); ?>-slides" data-nextsaas-testimonial-next><?php echo nextsaas_icon( 'arrow-right' ); ?></button></div></div></div></section>
